mapper.select:
select count(1)
from b_tcyr_cpa_push_data
where task_id = #{taskId}

select id, user_key, priority
from b_tcyr_cpa_push_data
where is_del = 1
  and colliding_date = curdate()
  and (
    priority > #{lastPriority}
        or (priority = #{lastPriority} and id > #{lastId})
    )
order by priority desc, id asc
    limit #{limit}
